const configured = flow.get('cpslai3_mode_tags') || {};
const nodeId = String(msg._nodeId || msg.topic || '').split(';datatype=')[0].trim();
const meta = configured[nodeId];
if (!meta || (msg._tag && msg._tag !== meta.tag)) { node.warn('Rejected unexpected CPS-LAI-03 OPC UA sample: ' + nodeId); return null; }
const batch = flow.get('cpslai3_mode_read_batch');
if (!batch || batch.batchId !== msg._batchId || Date.now() > batch.expiresAt || batch.received.includes(nodeId)) { node.warn('Rejected late, unknown or duplicate CPS-LAI-03 read response: ' + nodeId); return null; }
batch.received.push(nodeId);
flow.set('cpslai3_mode_read_batch', batch.received.length === batch.expected.length ? null : batch);

const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object || {}, key);
const raw = hasOwn(msg, 'value') ? msg.value
  : hasOwn(msg.payload, 'value') ? msg.payload.value
    : hasOwn(msg.payload?.attributes, 'value') ? msg.payload.attributes.value
      : undefined;
const dataTypeAttribute = msg.dataType ?? msg.dataTypeNodeId ?? msg.attributes?.dataType
  ?? msg.payload?.dataTypeNodeId ?? msg.payload?.attributes?.dataType ?? null;
const dataTypeNodeId = (() => {
  if (dataTypeAttribute === null || dataTypeAttribute === undefined || dataTypeAttribute === '') return null;
  if (typeof dataTypeAttribute === 'string') return dataTypeAttribute.trim();
  if (typeof dataTypeAttribute?.toString === 'function') {
    const text = dataTypeAttribute.toString();
    if (text && text !== '[object Object]') return text.trim();
  }
  const namespace = dataTypeAttribute.namespace ?? dataTypeAttribute.namespaceIndex;
  const value = dataTypeAttribute.value ?? dataTypeAttribute.identifier;
  if (Number(namespace) === 0 && value !== undefined) return 'ns=0;i=' + String(value);
  return null;
})();
const normalizedTypeToken = String(dataTypeNodeId || '').replace(/\s/g, '').toLowerCase();
