  dataType:booleanDataTypeProven ? 'Boolean' : null,
  dataTypeNodeId, dataTypeEvidence:dataTypeNodeId ? 'OPC_UA_ATTRIBUTE_DATATYPE' : null,
  statusCode, quality:statusCode, valid, timestamp:collectedAt, collectedAt,
  sourceTimestamp, serverTimestamp,
