        return null;
    }
}
if (!data || typeof data !== 'object' || Array.isArray(data)) return null;
if (data.cpsId && String(data.cpsId).trim().toLowerCase() !== 'cpslai3') {
    node.warn('Rejected lifecycle for unexpected cpsId');
    return null;
}
