  { role:'AUTOMATIC', tag:'sys_sup', nodeId:'ns=3;s="sys_sup"' },
  { role:'STEP_BY_STEP', tag:'sys_man2', nodeId:'ns=3;s="sys_man2"' }
];
const STALE_AFTER_MS = 6000;
