const lifecyclePhase = flow.get('cpslai3_lifecycle_phase') || null;
const publishedAt = new Date().toISOString();
const nowMs = Date.parse(publishedAt);
const data = {};
for (const marker of MARKERS) {
  const cached = samples[marker.tag];
  if (!cached) continue;
  const collectedAtMs = Date.parse(cached.collectedAt);
  const ageMs = Number.isFinite(collectedAtMs) ? Math.max(0, nowMs - collectedAtMs) : null;
  const stale = ageMs === null || ageMs > STALE_AFTER_MS;
