else if (entries.some(sample => !/^Good(?:\b|\s|\()/i.test(String(sample.statusCode || sample.quality || '')))) derived = result('UNKNOWN', 'BAD_OPCUA_QUALITY');
else if (entries.some(sample => typeof sample.value !== 'boolean')) derived = result('UNKNOWN', 'NON_BOOLEAN_MARKER_VALUE');
else {
  const active = entries.map(sample => sample.value);
  const activeCount = active.filter(Boolean).length;
  if (activeCount === 0) derived = result('UNKNOWN', 'NO_ACTIVE_MODE_MARKER');
  else if (activeCount > 1) derived = result('UNKNOWN', 'NON_EXCLUSIVE_MODE_MARKERS');
  else if (active[0]) derived = result('MANUAL', 'EXCLUSIVE_MANUAL_MARKER');
  else if (active[1]) derived = result('AUTOMATIC', 'EXCLUSIVE_AUTOMATIC_MARKER');
  else derived = result('STEP_BY_STEP', 'EXCLUSIVE_STEP_BY_STEP_MARKER');
}
const currentSamples = entries.filter(sample => sample && sample.stale !== true);
const dataFresh = currentSamples.length > 0;
const dataPayload = {
  schemaVersion:'1.2', cpsId:'cpslai3', formalCpsId:'CPS-LAI-03', assetName:'SortingStationLAI',
  displayName:'CPS-LAI-03 – Sorting Station', source:'OPC_UA',
  endpoint:'opc.tcp://192.168.1.30:4840', timestamp:publishedAt, publishedAt,
  snapshotComplete:entries.every(Boolean), availableTagCount:entries.filter(Boolean).length,
  expectedTagCount:MARKERS.length, staleAfterMs:STALE_AFTER_MS,
  communication:{ dataFresh, connected:communicationStatus.connected === true },
  data, derived
