  communication:{ dataFresh, connected:communicationStatus.connected === true, status:communicationStatus.status || {}, statusTimestamp:communicationStatus.timestamp || null },
  evidenceStatus:derived.operationMode === 'UNKNOWN' ? 'INSUFFICIENT_OR_INVALID_MODE_EVIDENCE' : 'PHYSICALLY_VALIDATED_MODE_MARKERS'
