return [
  { topic:'cpslai3/data', qos:1, retain:false, payload:JSON.stringify(dataPayload) },
  { payload:JSON.stringify(statusPayload) },
  { payload:JSON.stringify(oeePayload) }
];

flow.set('cpslai3_mode_samples', {});
flow.set('cpslai3_mode_read_batch', null);
flow.set('cpslai3_mode_tags', {});
